const DAILY_20260930=[{"id":"rosti","n":"Rösti (Swiss Crispy Potato Cake)","c":"Switzerland","f":"🇨🇭","m":35,"x":["potato","onion","butter","salt","black pepper","sour cream"],"s":["Coarsely grate the potato and squeeze out excess moisture.","Mix with finely sliced onion, salt, and black pepper.","Melt butter in a skillet, press the mixture into a flat cake, and cook until deeply golden.","Flip carefully, brown the second side, and serve with sour cream."],"co":"#c84e45","source":"https://www.myswitzerland.com/en/planning/about-switzerland/custom-and-tradition/typical-food-old/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"alplermagronen","n":"Älplermagronen (Swiss Alpine Macaroni)","c":"Switzerland","f":"🇨🇭","m":45,"x":["pasta","potato","cheese","cream","onion","apple"],"s":["Boil the potato cubes and pasta until just tender, then drain.","Layer the pasta and potato with cheese in a baking dish.","Pour over cream and bake until bubbling and lightly browned.","Top with crisp fried onion and serve with stewed apple."],"co":"#d2a64d","source":"https://www.myswitzerland.com/en-in/planning/about-switzerland/custom-and-tradition/typical-food/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"pastel-de-choclo","n":"Pastel de Choclo (Chilean Corn and Beef Pie)","c":"Chile","f":"🇨🇱","m":70,"x":["corn","ground beef","onion","chicken","egg","basil"],"s":["Cook ground beef and onion until the meat is browned and fully cooked.","Spread the beef mixture in a baking dish with cooked chicken and sliced boiled egg.","Blend corn with milk or water and basil, then cook until thick.","Spoon the corn topping over the filling and bake until golden."],"co":"#e0a83e","source":"https://chile.travel/en/blog/chilean-cuisine-day-what-does-chile-taste-like/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"cazuela-chilena","n":"Cazuela Chilena (Chilean Beef and Vegetable Stew)","c":"Chile","f":"🇨🇱","m":75,"x":["beef","pumpkin","potato","corn","carrot","onion"],"s":["Brown the beef lightly, then cover it with water and simmer.","Add onion and carrot and cook until the broth is flavorful.","Add pumpkin, potato, and corn and simmer until all vegetables are tender.","Season the clear broth and serve one piece of each main ingredient per bowl."],"co":"#b46c34","source":"https://chile.travel/en/blog/chilean-food-day-5-dishes-of-our-nations-gastronomy-you-must-try-2/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"taiwan-beef-noodle","n":"Niúròu Miàn (Taiwanese Beef Noodle Soup)","c":"Taiwan","f":"🇹🇼","m":110,"x":["beef","wheat noodles","soy sauce","ginger","garlic","bok choy"],"s":["Brown the beef, then add ginger, garlic, soy sauce, and water.","Simmer gently until the beef is tender and the broth is rich.","Cook the wheat noodles and bok choy separately.","Place noodles in a bowl, add beef and greens, and ladle over the hot broth."],"co":"#8d4239","source":"https://eng.taiwan.net.tw/att/0024052/04_0024052.pdf","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"lu-rou-fan","n":"Lǔròu Fàn (Taiwanese Braised Pork Rice)","c":"Taiwan","f":"🇹🇼","m":65,"x":["pork","rice","soy sauce","onion","egg","sugar"],"s":["Dice the pork and brown it slowly so some fat renders.","Add onion, soy sauce, sugar, and water, then simmer until glossy and tender.","Boil the egg, peel it, and warm it in the braising liquid.","Spoon the pork and sauce over hot rice and add the braised egg."],"co":"#9b5a36","source":"https://eng.taiwan.net.tw/m1.aspx?sNo=0024013","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"wiener-schnitzel","n":"Wiener Schnitzel (Austrian Breaded Veal Cutlet)","c":"Austria","f":"🇦🇹","m":30,"x":["veal","flour","egg","breadcrumbs","butter","lemon"],"s":["Pound the veal evenly thin and season it lightly.","Coat it in flour, beaten egg, and breadcrumbs without pressing the crumbs down.","Fry in hot clarified butter, moving the pan gently, until puffed and golden on both sides.","Drain briefly and serve immediately with lemon."],"co":"#cda34b","source":"https://www.austria.info/nl-nl/recepten/wiener-schnitzel/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"tafelspitz","n":"Tafelspitz (Austrian Boiled Beef)","c":"Austria","f":"🇦🇹","m":130,"x":["beef","beef broth","carrot","leek","potato","horseradish"],"s":["Bring the broth to a gentle simmer and add the beef.","Skim the surface, then add carrot and leek.","Cook below a full boil until the beef is tender, then rest and slice it across the grain.","Serve with boiled potato, vegetables, broth, and horseradish."],"co":"#7b6b4a","source":"https://www.austria.info/nl-nl/inspiratie/culinary-vienna/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"stuffat-tal-fenek","n":"Stuffat tal-Fenek (Maltese Rabbit Stew)","c":"Malta","f":"🇲🇹","m":120,"x":["rabbit","tomato","onion","garlic","red wine","potato"],"s":["Brown the rabbit pieces in a heavy pot and set them aside.","Soften onion and garlic, then add tomato and red wine.","Return the rabbit, add a little water, and simmer gently until tender.","Add potato for the final stage and cook until it absorbs the sauce."],"co":"#a3483d","source":"https://www.visitmalta.com/nl/blog/charming-chapels-timeless-towns-a-luxury-tour-through-malta%E2%80%99s-2000-years-of-unbroken-catholic-tradition","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"pastizzi","n":"Pastizzi (Maltese Ricotta Pastries)","c":"Malta","f":"🇲🇹","m":40,"x":["puff pastry","ricotta","egg","flour","olive oil","salt"],"s":["Mix ricotta with part of the beaten egg and a small pinch of salt.","Roll the pastry thin and cut it into even portions.","Add filling, fold into the traditional pointed shape, and seal the edges.","Brush with the remaining egg and bake until crisp and deeply golden."],"co":"#d6a755","source":"https://www.visitmalta.com/en/telegraph-families/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."}];
